import { readFileSync, writeFileSync } from "node:fs";
const { sha256, stableJson } = await import("/tmp/base/claude-plugin/skills/korean-prose-editor/scripts/lib.mjs");
const dir = new URL(".", import.meta.url).pathname;
const read = (name) => JSON.parse(readFileSync(`${dir}/${name}`, "utf8"));
const prep = read("prep.json");
const selection = read("selection.json");
const draft = read("editing-draft.json");
const { source } = prep;
for (const e of draft.edits) {
  if (e.sourceDigest !== prep.units.sourceDigest || e.actorId !== prep.actorIds[1]) throw new Error(`bad edit ${e.id}`);
}
let candidate = source;
for (const e of [...draft.edits].sort((a, b) => b.start - a.start)) candidate = candidate.slice(0, e.start) + e.replacement + candidate.slice(e.end);
const editing = {
  schemaVersion: "1.0.0",
  actorId: prep.actorIds[1],
  sourceDigest: prep.units.sourceDigest,
  glossaryBinding: prep.glossaryBinding,
  selectionDigest: sha256(stableJson(selection)),
  edits: draft.edits,
  candidateDigest: sha256(candidate),
};
writeFileSync(`${dir}/editing.json`, JSON.stringify(editing, null, 2));
console.log("editingDigest", sha256(stableJson(editing)));
console.log(candidate);

